const $ = (s, p=document) => p.querySelector(s);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm = s => String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const icon = name => `<svg class="icon" width="20" height="20" aria-hidden="true" focusable="false"><use href="icons.svg#${name}"/></svg>`;
const journalStyles = {
 bolema:['Bolema','#65469b','#f0eafa'], zetetike:['Zetetiké','#236c53','#e7f4ed'],
 emp:['EMP','#345fba','#eaf0fd'], revemat:['REVEMAT','#007782','#e5f4f5'],
 ripem:['RIPEM','#985123','#fff0e5'], emr:['EM em Revista','#a03c66','#fbeaf1'],
 remat:['REMAT · SP','#5149ad','#eeedfc'], pem:['Perspectivas EM','#8a6420','#fbf2dc'],
 rpem:['RPEM','#346b90','#e9f2fa'], boem:['BOEM','#5b712b','#f0f5e4'],
 emteia:['EM TEIA','#8b4b86','#f7eaf6'], jieem:['JIEEM','#9c4640','#fceeea'],
 rematec:['REMATEC','#42617c','#eaf0f6'], tangram:['Tangram','#3d7571','#e7f3f0'],
 histemat:['HISTEMAT','#73583f','#f4eee5']
};
const journalTheme=id=>journalStyles[id]||[id,'#456077','#edf2f7'];
const journalStyle=id=>{const [,ink,bg]=journalTheme(id);return `--journal-ink:${ink};--journal-bg:${bg}`};
const journalTag=id=>`<a class="journal-tag" style="${journalStyle(id)}" href="#revistas" title="${esc(journalName(id))}"><span class="journal-dot"></span>${esc(journalTheme(id)[0])}</a>`;
const safeURL = s => {try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const link = (url,label,cls='') => safeURL(url)?`<a class="${cls}" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${label} ${icon('arrow-up-right')}</a>`:'';
let data, journals, coverage, articles=[], page=1, query='', filters={journal:[],year:[]}, sort='newest', view='grid';
const PAGE_SIZE=10;
const main=$('#main'), modal=$('#record-dialog');
const journalName=id=>journals.find(j=>j.id===id)?.name||id;
function notify(text){const t=$('.toast');t.textContent=text;t.hidden=false;setTimeout(()=>t.hidden=true,3000)}
function facets(field){const counts=new Map();for(const a of articles){const values=[a[field]];for(const v of new Set(values||[])){if(v)counts.set(String(v),(counts.get(String(v))||0)+1)}}return [...counts].sort((a,b)=>field==='year'?b[0].localeCompare(a[0]):b[1]-a[1]||a[0].localeCompare(b[0],'pt-BR'))}
function filtered(){const terms=norm(query).trim().split(/\s+/).filter(Boolean);return articles.filter(a=>terms.every(t=>a.search.includes(t))&&Object.entries(filters).every(([k,values])=>!values.length||values.some(v=>String(a[k])===v))).sort((a,b)=>sort==='title'?a.title.localeCompare(b.title,'pt-BR'):sort==='oldest'?a.year-b.year:b.year-a.year)}
function filterHTML(){return `<div class="filter-heading"><h2>${icon('sliders-horizontal')} Filtros</h2><button class="link-button" id="clear">Limpar</button></div>`+[['journal','Revistas'],['year','Ano de publicação']].map(([field,label])=>`<details open class="filter-section"><summary>${icon(field==='journal'?'library-big':'calendar-days')}${label}${icon('chevron-down')}</summary><div class="options">${facets(field).map(([v,n])=>`<label class="check"><input type="checkbox" data-field="${field}" value="${esc(v)}" ${filters[field].includes(v)?'checked':''}>${field==='journal'?`<span class="filter-dot" style="${journalStyle(v)}"></span>`:''}<span class="check-label" title="${esc(field==='journal'?journalName(v):v)}">${esc(field==='journal'?journalName(v):v)}</span><small>${n.toLocaleString('pt-BR')}</small></label>`).join('')||'<span class="count-pill">Sem informação</span>'}</div></details>`).join('')+`<a class="coverage-link" href="#dados">${icon('info')}Cobertura do acervo</a>`}
function articleHTML(a){return `<article class="article" style="${journalStyle(a.journal)}"><div class="article-top">${journalTag(a.journal)}<span class="article-year">${icon('calendar-days')}${esc(a.year||'s.d.')}</span></div><h3><a href="#artigo/${encodeURIComponent(a.id)}">${esc(a.title)}</a></h3><p class="authors">${icon('users')}<span>${esc(a.authors.join('; '))}</span></p>${a.abstract?`<p class="abstract abstract-preview">${esc(a.abstract)}</p><details class="abstract-details"><summary><span class="when-closed">Ler resumo completo</span><span class="when-open">Recolher resumo</span>${icon('chevron-down')}</summary><p class="abstract">${esc(a.abstract)}</p></details>`:'<p class="missing">Resumo em português não disponível nos metadados.</p>'}${a.keywords.length?`<div class="keyword-tags" aria-label="Palavras-chave">${a.keywords.slice(0,3).map(k=>`<span class="tag">${esc(k)}</span>`).join('')}${a.keywords.length>3?`<a class="tag extra-tags" href="#artigo/${encodeURIComponent(a.id)}" aria-label="Ver todas as palavras-chave">+${a.keywords.length-3}</a>`:''}</div>`:''}<div class="article-links">${link(a.url,icon('book-open')+'Ler artigo','read-link')}<a class="reference-link" href="#artigo/${encodeURIComponent(a.id)}">${icon('quote')}Referência</a>${a.pdf?link(a.pdf,icon('file-text')+'PDF','pdf-link'):''}</div></article>`}
function updateResults(){const rows=filtered(), total=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));page=Math.min(page,total);$('#results-count').textContent=`${rows.length.toLocaleString('pt-BR')} resultado${rows.length===1?'':'s'}`;$('#results-title').textContent=query||Object.values(filters).some(v=>v.length)?'Resultados da busca':'Publicações';$('#articles').classList.toggle('list-view',view==='list');$('#articles').innerHTML=rows.length?rows.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE).map(articleHTML).join(''):'<div class="empty"><h2>Nenhum artigo encontrado</h2><p>Tente outros termos ou remova alguns filtros.</p><button class="btn" id="reset-search">Limpar busca e filtros</button></div>';$('#pagination').innerHTML=rows.length?`<button class="btn" id="prev" ${page===1?'disabled':''}>${icon('chevron-left')}Anterior</button><span>Página ${page} de ${total}</span><button class="btn" id="next" ${page===total?'disabled':''}>Próxima${icon('chevron-right')}</button>`:'';if($('#prev'))$('#prev').onclick=()=>{page--;updateResults();$('#results-title').scrollIntoView({block:'start'})};if($('#next'))$('#next').onclick=()=>{page++;updateResults();$('#results-title').scrollIntoView({block:'start'})};if($('#reset-search'))$('#reset-search').onclick=reset;}
function reset(){query='';for(const k in filters)filters[k]=[];page=1;searchPage()}
function searchPage(){main.innerHTML=`<section class="hero"><div class="hero-heading"><div><span class="eyebrow">BUSCA INTEGRADA EM PERIÓDICOS</span><h1>Pesquise em Educação Matemática<span class="title-dot">.</span></h1></div><a class="source-count" href="#revistas">${icon('library-big')}<strong>${new Set(articles.map(a=>a.journal)).size}</strong> revistas reunidas</a></div><form class="search" role="search">${icon('search')}<label class="sr-only" for="query">Pesquisar no acervo</label><input id="query" type="search" value="${esc(query)}" placeholder="Título, autoria, assunto ou DOI"><button>${icon('search')}Buscar artigos</button></form><div class="summary"><span>${icon('file-text')}<strong>${articles.length.toLocaleString('pt-BR')}</strong> publicações para explorar</span><span>${icon('calendar-days')}Atualizado em ${esc(data.updated?new Date(data.updated).toLocaleDateString('pt-BR'):'data não informada')}</span></div></section><div class="workspace"><button class="btn filter-toggle" aria-expanded="false">${icon('sliders-horizontal')}Mostrar filtros</button><aside class="filters" aria-label="Filtros de pesquisa">${filterHTML()}</aside><section class="results" aria-label="Resultados"><div class="results-head"><div class="result-heading"><h2 id="results-title">Publicações</h2><span id="results-count" role="status"></span></div><div class="results-meta"><label for="sort">${icon('arrow-down-up')}<span class="sr-only">Ordenar resultados</span></label><select id="sort"><option value="newest">Mais recentes</option><option value="oldest">Mais antigos</option><option value="title">Título: A–Z</option></select><div class="view-switch" role="group" aria-label="Visualização"><button id="grid-view" title="Cards em duas colunas" aria-label="Cards em duas colunas" aria-pressed="${view==='grid'}">${icon('layout-grid')}</button><button id="list-view" title="Cards em uma coluna" aria-label="Cards em uma coluna" aria-pressed="${view==='list'}">${icon('list')}</button></div></div></div><div id="articles"></div><div class="pagination" id="pagination"></div></section></div>`;
 $('#sort').value=sort;
 $('.search').onsubmit=e=>{e.preventDefault();query=$('#query').value.trim();page=1;updateResults()};
 $('#sort').onchange=e=>{sort=e.target.value;page=1;updateResults()};
 $('#clear').onclick=()=>{for(const k in filters)filters[k]=[];page=1;searchPage()};
 $('.filter-toggle').onclick=e=>{const open=$('.filters').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.innerHTML=icon('sliders-horizontal')+(open?'Ocultar filtros':'Mostrar filtros')};
 for(const mode of ['grid','list'])$('#'+mode+'-view').onclick=()=>{view=mode;for(const m of ['grid','list'])$('#'+m+'-view').setAttribute('aria-pressed',m===mode);updateResults()};
 document.querySelectorAll('[data-field]').forEach(input=>input.onchange=()=>{const values=filters[input.dataset.field];input.checked?values.push(input.value):values.splice(values.indexOf(input.value),1);page=1;updateResults()});updateResults();}
function simplePage(eyebrow,title,content){main.innerHTML=`<section class="page"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${content}</section>`}
function statusLabel(id){const c=coverage.journals.find(c=>c.id===id);return c?.status==='ok'?'Paginação OAI concluída':c?.status==='partial'?'Coleta em andamento':c?.status==='error'?'Atualização indisponível':'Não integrada'}
function journalsPage(){simplePage('O acervo','Revistas integradas',`<p class="intro">Publicações reunidas diretamente das revistas. A cobertura corresponde aos registros que cada fonte disponibiliza por OAI-PMH.</p>${journals.filter(j=>j.enabled).map(j=>`<div class="journal" style="${journalStyle(j.id)}"><div>${journalTag(j.id)}<div class="eyebrow">${esc(j.publisher)}</div><h2>${esc(j.name)}</h2><p>${articles.filter(a=>a.journal===j.id).length.toLocaleString('pt-BR')} publicações · ${statusLabel(j.id)}</p>${j.coverageNote?`<p class="coverage-note">${esc(j.coverageNote)}</p>`:''}</div><div class="actions"><button class="btn" data-journal="${esc(j.id)}">Explorar publicações</button>${link(j.url,'Site da revista')}</div></div>`).join('')}`);document.querySelectorAll('[data-journal]').forEach(b=>b.onclick=()=>{for(const k in filters)filters[k]=[];query='';filters.journal=[b.dataset.journal];page=1;location.hash='#buscar'})}
function dataPage(){simplePage('Transparência','Dados do acervo',`<p class="intro">${data.demo?'Estatísticas de demonstração. Nenhuma coleta real está sendo representada.':'Contagens calculadas a partir dos registros disponíveis nesta versão.'}</p><div class="metrics"><div class="metric"><strong>${articles.length}</strong>Registros</div><div class="metric"><strong>${new Set(articles.map(a=>a.journal)).size}</strong>Revistas com registros</div><div class="metric"><strong>${articles.filter(a=>a.doi).length}</strong>Registros com DOI</div></div><div class="table-wrap"><table><thead><tr><th>Revista</th><th>Registros</th><th>Sem resumo em português</th><th>Sem DOI</th><th>Coleta</th></tr></thead><tbody>${journals.filter(j=>j.enabled).map(j=>{const aa=articles.filter(a=>a.journal===j.id);return `<tr><td>${esc(j.name)}</td><td>${aa.length}</td><td>${aa.filter(a=>!a.abstract).length}</td><td>${aa.filter(a=>!a.doi).length}</td><td>${statusLabel(j.id)}${j.coverageNote?`<br><small>${esc(j.coverageNote)}</small>`:''}</td></tr>`}).join('')}</tbody></table></div><p><a href="data/status.json" target="_blank">Consultar relatório técnico de coleta</a></p>`)}
function aboutPage(){simplePage('O projeto','Uma busca, diferentes revistas.',`<div class="intro"><p>O BuscaEM reúne metadados de periódicos brasileiros especializados em Educação Matemática. Não é uma rede social nem um novo periódico. A publicação original e o crédito editorial permanecem com cada revista.</p><h2>Procedência e limites</h2><p>O coletor consulta OAI-PMH e preserva os registros XML originais. Títulos e autoria são preservados. Resumos e palavras-chave são exibidos apenas quando identificados como português; textos sem identificação confiável são omitidos da exibição. Não são feitas traduções automáticas. Informações ausentes não são inventadas. Editoriais e outros tipos permanecem identificados quando a fonte informa essa distinção.</p><p>A busca desta versão consulta metadados, não o texto completo dos PDFs. Ela ignora acentos e exige a presença de todas as palavras digitadas, sem operadores booleanos. Os filtros dentro de uma categoria são alternativos; categorias diferentes são combinadas.</p><h2>Leitura e dados</h2><p>Os artigos são abertos nas revistas de origem. PDFs não são copiados para este site. A classificação de acesso aberto só aparece quando informada no registro tratado.</p><p>Esta primeira versão estática usa GitHub e Cloudflare Pages. A coleta OAI-PMH está incluída; um servidor OAI-PMH de saída e uma API de produção não estão implementados nesta versão.</p></div>`)}
function citation(a){return `${a.authors.join('; ')}. ${a.title}. ${journalName(a.journal)}, ${a.year||'s.d.'}.${a.doi?' https://doi.org/'+a.doi:''}`}
function download(text,name,mime){const u=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function record(id){const a=articles.find(a=>a.id===id);if(!a){simplePage('Registro','Artigo não encontrado','<p>O endereço pode ter mudado. <a href="#buscar">Voltar à busca</a>.</p>');return}if(!$('#articles'))searchPage();$('#record-content').innerHTML=`${journalTag(a.journal)}<h2 id="record-title" class="record-title">${esc(a.title)}</h2><p class="authors">${esc(a.authors.join('; '))}</p><div class="tags">${a.keywords.map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div><h3>Resumo</h3><p class="abstract">${esc(a.abstract||'Resumo em português não disponível nos metadados.')}</p><dl class="record-details"><dt>Revista</dt><dd>${esc(journalName(a.journal))}</dd><dt>Ano</dt><dd>${esc(a.year||'Não informado')}</dd><dt>Idioma</dt><dd>${esc(a.language||'Não informado')}</dd><dt>Tipo</dt><dd>${esc(a.type||'Não informado')}</dd><dt>DOI</dt><dd>${a.doi?link('https://doi.org/'+a.doi,esc(a.doi)):'Não informado'}</dd><dt>Identificador OAI</dt><dd>${esc(a.oaiIdentifier||'Não disponível nesta demonstração')}</dd><dt>Fonte do registro</dt><dd>${data.demo?'Dados fictícios para teste':esc(a.source||'OAI-PMH')}</dd><dt>Coletado em</dt><dd>${esc(a.harvestedAt||'Não coletado')}</dd></dl><div class="record-actions">${link(a.url,'Ler na revista','btn primary')}${link(a.pdf,'PDF na fonte','btn')}<button class="btn" id="ris">Exportar RIS</button><button class="btn" id="bib">Exportar BibTeX</button><button class="btn" id="csv">Exportar CSV</button></div><h3>Referência</h3><p class="citation">${esc(citation(a))}</p><button class="btn" id="copy">${icon('quote')}Copiar referência</button>`;
$('#ris').onclick=()=>download(['TY  - JOUR',...a.authors.map(n=>'AU  - '+n),'TI  - '+a.title,'JO  - '+journalName(a.journal),'PY  - '+(a.year||''),'DO  - '+(a.doi||''),'UR  - '+(a.url||''),'AB  - '+(a.abstract||''),...a.keywords.map(k=>'KW  - '+k),'ER  -',''].join('\r\n'),'referencia.ris','application/x-research-info-systems');
$('#bib').onclick=()=>{const clean=s=>String(s||'').replace(/\\/g,'\\textbackslash{}').replace(/[{}]/g,'').replace(/[%&#_]/g,'\\$&');download(`@article{buscaem${a.year||''},\n title={${clean(a.title)}},\n author={${a.authors.map(clean).join(' and ')}},\n journal={${clean(journalName(a.journal))}},\n year={${a.year||''}},\n doi={${clean(a.doi)}},\n url={${clean(a.url)}}\n}\n`,'referencia.bib','text/plain')};
$('#csv').onclick=()=>{const cell=v=>'"'+String(v||'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('\ufefftitulo;autores;revista;ano;doi;url\n'+[a.title,a.authors.join('; '),journalName(a.journal),a.year,a.doi,a.url].map(cell).join(';'),'referencia.csv','text/csv;charset=utf-8')};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(citation(a));notify('Referência copiada.')}catch{notify('Selecione a referência e copie com Ctrl/Cmd+C.')}};if(!modal.open)modal.showModal();}
$('.close').onclick=()=>modal.close();modal.addEventListener('close',()=>{if(!modal.open&&location.hash.startsWith('#artigo/')){history.replaceState(null,'','#buscar')}});
function route(){if(modal.open)modal.close();const hash=location.hash==='#inicio'?'#buscar':location.hash||'#buscar';document.querySelectorAll('nav a').forEach(a=>{const active=a.getAttribute('href')===hash;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});if(hash.startsWith('#artigo/')){try{record(decodeURIComponent(hash.slice(8)))}catch{searchPage()}}else if(hash==='#revistas')journalsPage();else if(hash==='#dados')dataPage();else if(hash==='#sobre')aboutPage();else searchPage();}
const originalSearchPage=searchPage;
searchPage=function(){originalSearchPage();if(!data.demo&&data.partial){$('.hero').insertAdjacentHTML('afterend','<div class="notice">Algumas fontes ainda estão em atualização. <a href="#dados">Consultar cobertura</a></div>')}};
try{const responses=await Promise.all([fetch('data/catalog.json'),fetch('data/journals.json'),fetch('data/status.json')]);if(responses.some(r=>!r.ok))throw Error('dados indisponíveis');[data,journals,coverage]=await Promise.all(responses.map(r=>r.json()));const chunks=await Promise.all(data.chunks.map(async name=>{const r=await fetch('data/'+name);if(!r.ok)throw Error('lote indisponível');return r.json()}));articles=chunks.flat().map(a=>({...a,authors:a.authors||[],keywords:a.keywords||[],search:norm([a.title,...(a.authors||[]),a.abstract,...(a.keywords||[]),a.doi,journalName(a.journal)].join(' '))}));window.addEventListener('hashchange',route);route()}catch(error){main.innerHTML='<section class="empty"><h1>Não foi possível carregar o acervo.</h1><p>Verifique a conexão e tente novamente. Para abrir o projeto no computador, use o servidor local indicado no README.</p><button class="btn" onclick="location.reload()">Tentar novamente</button></section>';console.error(error)}
